.container {
  width: 100%;
  max-width: 600px;
  background: white;
  border-radius: 12px;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
  padding: 2rem;
}

h1 {
  color: #333;
  text-align: center;
  margin-bottom: 2rem;
  font-size: 2rem;
}

.message-list {
  max-height: 500px;
  overflow-y: auto;
  margin-bottom: 2rem;
  padding: 0 0.5rem;
}

.message {
  padding: 1rem;
  border-bottom: 1px solid #eee;
  animation: fadeIn 0.3s ease-in;
}

.message:last-child {
  border-bottom: none;
}

.message .timestamp {
  font-size: 0.75rem;
  color: #888;
  margin-bottom: 0.5rem;
}

.message .text {
  color: #333;
  word-wrap: break-word;
}

.message-form {
  display: flex;
  gap: 0.5rem;
}

.message-form input {
  flex: 1;
  padding: 0.75rem 1rem;
  border: 2px solid #e0e0e0;
  border-radius: 8px;
  font-size: 1rem;
  transition: border-color 0.2s;
}

.message-form input:focus {
  outline: none;
  border-color: #667eea;
}

.message-form button {
  padding: 0.75rem 1.5rem;
  background: #667eea;
  color: white;
  border: none;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s;
}

.message-form button:hover {
  background: #5568d3;
}

.message-form button:active {
  transform: scale(0.98);
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(-10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
