body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  padding: 2rem 1rem;
}

.container {
  width: 100%;
  max-width: 600px;
  background: white;
  border-radius: 12px;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
  padding: 2rem;
}

h1 {
  color: #333;
  text-align: center;
  margin-bottom: 2rem;
  font-size: 2rem;
}

.message-list {
  max-height: 500px;
  overflow-y: auto;
  margin-bottom: 2rem;
  padding: 0 0.5rem;
}

.message {
  padding: 1rem;
  border-bottom: 1px solid #eee;
  animation: fadeIn 0.3s ease-in;
}

.message:last-child {
  border-bottom: none;
}

.message .timestamp {
  font-size: 0.75rem;
  color: #888;
  margin-bottom: 0.5rem;
}

.message .text {
  color: #333;
  word-wrap: break-word;
}

.message-form {
  display: flex;
  gap: 0.5rem;
}

.message-form input {
  flex: 1;
  padding: 0.75rem 1rem;
  border: 2px solid #e0e0e0;
